import 'package:flutter/material.dart';
import '../services/notification_preferences_service.dart';
class NotificationPreferencesScreen extends StatefulWidget { const NotificationPreferencesScreen({super.key,required this.service}); final NotificationPreferencesService service; @override State<NotificationPreferencesScreen> createState()=>_State(); }
class _State extends State<NotificationPreferencesScreen>{Map<String,dynamic> p={};bool loading=true;@override void initState(){super.initState();_load();}Future<void> _load()async{final v=await widget.service.load();if(mounted)setState((){p=Map<String,dynamic>.from(v);loading=false;});}Future<void> _set(String key,bool value)async{setState(()=>p[key]=value);await widget.service.update({key:value});}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Notification preferences')),body:loading?const Center(child:CircularProgressIndicator()):ListView(children:[for(final e in const {'in_app':'In-app notifications','push':'Push notifications','email':'Email notifications','events':'Events','discipleship':'Discipleship','opportunities':'Opportunities','donations':'Donations','life_groups':'Life Groups'}.entries)SwitchListTile(title:Text(e.value),value:p[e.key]??true,onChanged:(v)=>_set(e.key,v))]));}
